import { Color, Icon, MenuBarExtra, showHUD, showToast, Toast } from "@raycast/api";
import { exec } from "child_process";
import { useEffect, useState } from "react";
import { promisify } from "util";

const execPromise = promisify(exec);
const CTL_BIN = "/opt/homebrew/bin/omniwmctl";

interface Workspace {
  displayName: string;
  isFocused: boolean;
  isVisible: boolean;
  layout: string;
  rawName: string;
}

interface WindowItem {
  id: string;
  title: string;
  app: {
    name: string;
    bundleId: string;
  };
  workspace: {
    displayName: string;
  };
}

export default function Command() {
  const [activeWorkspace, setActiveWorkspace] = useState<string>("1");
  const [activeLayout, setActiveLayout] = useState<string>("niri");
  const [workspaces, setWorkspaces] = useState<Workspace[]>([]);
  const [windows, setWindows] = useState<WindowItem[]>([]);

  useEffect(() => {
    async function updateStatus() {
      try {
        // Query workspaces
        const wsOut = await execPromise(`${CTL_BIN} query workspaces --json`);
        const wsResponse = JSON.parse(wsOut.stdout);
        const wsList = (wsResponse?.result?.payload?.workspaces || []) as Workspace[];
        setWorkspaces(wsList);

        const activeWs = wsList.find((w) => w.isFocused || w.isVisible);
        if (activeWs) {
          setActiveWorkspace(activeWs.displayName);
          setActiveLayout(activeWs.layout);
        }

        // Query active windows
        const winOut = await execPromise(`${CTL_BIN} query windows --json`);
        const winResponse = JSON.parse(winOut.stdout);
        setWindows(winResponse?.result?.payload?.windows || []);
      } catch (err) {
        // Fail silently
      }
    }

    updateStatus();
    const interval = setInterval(updateStatus, 3000); // Poll status every 3 seconds
    return () => clearInterval(interval);
  }, []);

  async function runOmniCommand(cmd: string, successMsg: string) {
    try {
      await execPromise(`${CTL_BIN} ${cmd}`);
      await showHUD(successMsg);
    } catch (error: any) {
      await showToast({
        style: Toast.Style.Failure,
        title: "Command failed",
        message: error.message,
      });
    }
  }

  // Layout Icon Indicator
  const layoutSymbol = activeLayout === "niri" ? "◈" : "⊞";

  return (
    <MenuBarExtra
      title={`${activeWorkspace} ${layoutSymbol}`}
      tooltip={`OmniWM Status (WS ${activeWorkspace} - ${activeLayout})`}
    >
      <MenuBarExtra.Section title="Workspaces">
        {workspaces.map((ws) => (
          <MenuBarExtra.Item
            key={ws.rawName}
            title={`Workspace ${ws.displayName} (${ws.layout})`}
            icon={ws.isFocused ? Icon.CircleProgress100 : Icon.Circle}
            onAction={() => runOmniCommand(`command switch-workspace ${ws.rawName}`, `Switched to WS ${ws.displayName}`)}
          />
        ))}
      </MenuBarExtra.Section>

      <MenuBarExtra.Section title="Active Windows">
        {windows
          .filter((w) => w.workspace?.displayName === activeWorkspace)
          .map((win) => (
            <MenuBarExtra.Item
              key={win.id}
              title={`${win.app?.name}: ${win.title || "Untitled"}`}
              icon={Icon.Window}
              onAction={() => runOmniCommand(`window focus ${win.id}`, "Focused window")}
            />
          ))}
      </MenuBarExtra.Section>

      <MenuBarExtra.Section title="Layout Operations">
        <MenuBarExtra.Item
          title="Toggle Full Width"
          icon={Icon.Maximize}
          onAction={() => runOmniCommand("command toggle-container-full-primary-span", "Toggled full width")}
        />
        <MenuBarExtra.Item
          title="Balance Sizes"
          icon={Icon.AppWindow}
          onAction={() => runOmniCommand("command balance-sizes", "Balanced window sizes")}
        />
        <MenuBarExtra.Item
          title="Toggle Floating Window"
          icon={Icon.List}
          onAction={() => runOmniCommand("command toggle-focused-window-floating", "Toggled float state")}
        />
        <MenuBarExtra.Item
          title="Toggle Workspace Bar"
          icon={Icon.Sidebar}
          onAction={() => runOmniCommand("command toggle-workspace-bar", "Toggled workspace bar")}
        />
      </MenuBarExtra.Section>
    </MenuBarExtra>
  );
}
